def deduplicate(data, key=None):
    """
    Remove duplicate entries from the input data.

    :param data: Input data to deduplicate.
    :type data: list or pandas.Series
    :param key: Function or column name to use for deduplication. If None, deduplicates based on the whole row.
    :type key: callable or str, optional
    :return: Deduplicated data.
    :rtype: list or pandas.Series
    """
    import pandas as pd

    if isinstance(data, pd.Series):
        return data.drop_duplicates(keep='first', inplace=False)
    elif isinstance(data, list):
        return list(dict.fromkeys(data))
    else:
        raise ValueError("Unsupported data type. Please provide a list or pandas.Series.")
